import json, re
from pathlib import Path

ROOT = Path(__file__).resolve().parent
LEDGER = json.loads((ROOT / "system_ledger.json").read_text(encoding="utf-8"))["chapters"]
FILES = {}
for p in ROOT.glob("Chương *.txt"):
    m = re.match(r"Chương\s+(\d+)\s+-", p.name)
    if m:
        FILES.setdefault(int(m.group(1)), []).append(p)

BAD_PATTERNS = {
    "meta_ai": re.compile(r"(?i)\b(?:as an ai|language model|chatgpt|openai|prompt|generated by ai)\b"),
    "placeholder": re.compile(r"(?i)(?:\bTODO\b|\bTBD\b|\[\s*(?:insert|placeholder)[^\]]*\]|<\s*(?:insert|placeholder)[^>]*>)"),
    "tool_remnant": re.compile(r"(?im)^\s*(?:assistant|user|system|developer|tool)\s*(?:[:：]|$)"),
    "generation_remnant": re.compile(r"(?i)(?:tiếp tục viết chương|hãy viết chương|rewrite this chapter|continue writing|word count\s*[:=])"),
}
HEADER_RE = re.compile(r"\A={20,}\r?\nChương\s+(\d+)\s*:\s*([^\r\n]+)\r?\n={20,}\r?\n")
PANEL_RE = re.compile(r"「Hệ thống\s*[—-]\s*GHI NHẬN ch\.(\d+)」\s*\r?\nNăm:\s*(\d{4})", re.I)
WORDS_RE = re.compile(r"\b[^\W\d_]+(?:[-’'][^\W\d_]+)*\b", re.UNICODE)

def scan():
    out = {"missing": [], "duplicate": {}, "year": [], "bad": [], "short": [], "hdr": [], "stats": {}}
    for n in range(1, 361):
        ps = FILES.get(n, [])
        if not ps:
            out["missing"].append(n); continue
        if len(ps) != 1:
            out["duplicate"][n] = [p.name for p in ps]; continue
        p = ps[0]
        text = p.read_text(encoding="utf-8-sig")
        expected_year = int(LEDGER[str(n)]["year"])
        h = HEADER_RE.search(text)
        expected_title = re.sub(r"^Chương\s+\d+\s+-\s*", "", p.stem)
        if not h or int(h.group(1)) != n or h.group(2).strip() != expected_title.strip():
            out["hdr"].append({"chapter": n, "file": p.name, "found": h.group(0)[:160] if h else text[:160], "expected": f"Chương {n}: {expected_title}"})
        panels = PANEL_RE.findall(text)
        if len(panels) != 1 or int(panels[0][0]) != n or int(panels[0][1]) != expected_year:
            out["year"].append({"chapter": n, "file": p.name, "expected": expected_year, "panels": panels})
        for kind, pat in BAD_PATTERNS.items():
            for m in pat.finditer(text):
                line = text.count("\n", 0, m.start()) + 1
                out["bad"].append({"chapter": n, "file": p.name, "kind": kind, "line": line, "text": text[m.start():m.end()]})
        words = len(WORDS_RE.findall(text))
        if words < 3000:
            out["short"].append({"chapter": n, "file": p.name, "words": words})
    out["stats"] = {"files": sum(len(v) for v in FILES.values()), "chapters": len(FILES), "year": len(out["year"]), "bad": len(out["bad"]), "short": len(out["short"]), "hdr": len(out["hdr"]), "missing": len(out["missing"]), "duplicate": len(out["duplicate"])}
    return out

if __name__ == "__main__":
    result = scan()
    (ROOT / "_structural_scan_360.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps(result["stats"], ensure_ascii=False))
    for key in ("year", "bad", "short", "hdr", "missing", "duplicate"):
        if result[key]: print(f"\n{key.upper()}: {json.dumps(result[key], ensure_ascii=False)[:8000]}")
